-- テーブル削除
-- DROP TABLE SYNC_COOP_CONVERT_SET CASCADE CONSTRAINTS;
declare
      num number;
begin
    select count(1) into num from user_tables where table_name = upper('SYNC_COOP_CONVERT_SET') ;
    if num > 0 then
        execute immediate 'drop table SYNC_COOP_CONVERT_SET CASCADE CONSTRAINTS' ;
    end if;
end;
/
-- テーブル作成
CREATE TABLE SYNC_COOP_CONVERT_SET
(
    NO                NUMBER(2)        PRIMARY KEY,
    MAKER_NAME        VARCHAR2(50),     -- メーカー名
    SYSTEM_NAME       VARCHAR2(50),     -- システム名
    FNW_COOP_ID       VARCHAR2(20),     -- FNW COOP_ID
    FNSI_COOP_VERSION VARCHAR2(20),     -- FNSi coop_version
    CONVERT_RULE      VARCHAR2(200),    -- コンバート方法
    REMARKS           VARCHAR2(200)     -- 備考
)
    tablespace NKK_DATA_COP;
-- コメント追加
COMMENT ON TABLE "SYNC_COOP_CONVERT_SET" IS '設定値';

COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."NO" IS '予約方法';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."MAKER_NAME" IS '桁保留';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."SYSTEM_NAME" IS '血液回路';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."FNW_COOP_ID" IS '穿刺針(A針)';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."FNSI_COOP_VERSION" IS '穿刺針(V針)';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."CONVERT_RULE" IS '穿刺針(SN)';
COMMENT ON COLUMN "SYNC_COOP_CONVERT_SET"."REMARKS" IS '観察記録種別';

